#!/usr/bin/env bash
# Render the soldering guide illustrations (#0667) from SVG to PNG.
#
#   scripts/render-soldering-art.sh            # assets/guides/soldering -> web/public/img/guides/soldering
#   scripts/render-soldering-art.sh SRC DEST   # any other directory of SVGs
#
# Each NAME.svg becomes NAME.png (1x, the SVG's own size) and NAME@2x.png.
# The SVGs are the source of truth. Most are generated by the two Python
# scripts beside them (gen_joints.py, gen_tinning.py), which take the output
# directory as their only argument; edit those and re-run them, then this.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
SRC="${1:-$ROOT/assets/guides/soldering}"
DEST="${2:-$ROOT/web/public/img/guides/soldering}"

command -v rsvg-convert >/dev/null || { echo "rsvg-convert not found (brew install librsvg)" >&2; exit 1; }

mkdir -p "$DEST"
count=0
for svg in "$SRC"/*.svg; do
  [ -e "$svg" ] || continue
  name="$(basename "$svg" .svg)"
  rsvg-convert --zoom=1 "$svg" -o "$DEST/$name.png"
  rsvg-convert --zoom=2 "$svg" -o "$DEST/$name@2x.png"
  count=$((count + 1))
done
[ "$count" -gt 0 ] || { echo "no SVGs in $SRC" >&2; exit 1; }
echo "rendered $count illustrations into $DEST"
